// Checks app code against the design system rules in AGENTS.md.
//
//   npm run ds:audit
//
// Fails on:
// - hardcoded colours (hex, rgb(), hsl(), oklch()) outside src/app/globals.css
// - arbitrary Tailwind values (p-[13px], text-[#fff]); arbitrary variants
//   such as data-[size=sm]: or [&_svg]: are allowed
// - pages (src/app/**) importing UI from anywhere except @/design-system and
//   @/components/ui
//
// src/components/ui/ holds shadcn primitives generated by the shadcn CLI, so
// it is not audited. Runs with Node's built-in TypeScript support, so it uses
// only erasable syntax and Node built-ins.

import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const AUDITED_DIRS = ["src/app", "src/design-system", "src/hooks", "src/lib", "src/data"];
const TOKENS_FILE = "src/app/globals.css";
const PAGES_DIR = "src/app";
const SOURCE_FILE = /\.(ts|tsx|css)$/;

// Imports a page may use that are not UI: framework, data, helpers, icons
// and the toast function. Everything else (other @/ paths, relative files,
// UI libraries) must come through @/design-system or @/components/ui.
const PAGE_IMPORTS_ALLOWED = [
  /^@\/design-system$/,
  /^@\/components\/ui\/[\w-]+$/,
  /^@\/lib\//,
  /^@\/hooks\//,
  /^react$/,
  /^next(\/|$)/,
  /^lucide-react$/,
  /^sonner$/,
  /\.css$/,
];

const COLOUR = /(?<![\w&-])#(?:[0-9a-f]{8}|[0-9a-f]{6}|[0-9a-f]{3,4})\b|\b(?:rgba?|hsla?|oklch)\(/gi;
// A utility followed by -[value] that is not itself a variant (ending in ":").
const ARBITRARY_VALUE = /(?<![\w[-])(?:[a-z][\w-]*:)*[a-z][\w-]*-\[[^\]\s]+\](?!:)/g;
const IMPORT = /^\s*(?:import|export)\b[^"']*?from\s+["']([^"']+)["']|^\s*import\s+["']([^"']+)["']/gm;

type Problem = { file: string; line: number; message: string };

function sourceFiles(dir: string): string[] {
  let entries: string[];
  try {
    entries = readdirSync(dir, { recursive: true }) as string[];
  } catch {
    return [];
  }
  return entries.filter((entry) => SOURCE_FILE.test(entry)).map((entry) => join(dir, entry));
}

function lineOf(text: string, index: number): number {
  return text.slice(0, index).split("\n").length;
}

// Blank out comments so example values in them don't count, keeping line
// numbers intact.
function stripComments(text: string): string {
  const blank = (match: string) => match.replace(/[^\n]/g, " ");
  return text.replace(/\/\*[\s\S]*?\*\//g, blank).replace(/^\s*\/\/.*$/gm, blank);
}

const problems: Problem[] = [];

for (const file of AUDITED_DIRS.flatMap(sourceFiles)) {
  if (file === TOKENS_FILE) continue;
  const text = stripComments(readFileSync(file, "utf8"));

  for (const match of text.matchAll(COLOUR)) {
    problems.push({
      file,
      line: lineOf(text, match.index),
      message: `hardcoded colour "${match[0]}": use a token from ${TOKENS_FILE}`,
    });
  }

  if (!file.endsWith(".css")) {
    for (const match of text.matchAll(ARBITRARY_VALUE)) {
      problems.push({
        file,
        line: lineOf(text, match.index),
        message: `arbitrary value "${match[0]}": use a token or the Tailwind scale`,
      });
    }
  }

  if (file.startsWith(PAGES_DIR + "/") && /\.tsx?$/.test(file)) {
    for (const match of text.matchAll(IMPORT)) {
      const source = match[1] ?? match[2];
      if (PAGE_IMPORTS_ALLOWED.some((allowed) => allowed.test(source))) continue;
      problems.push({
        file,
        line: lineOf(text, match.index),
        message: `page imports "${source}": import UI from @/design-system or @/components/ui`,
      });
    }
  }
}

if (problems.length > 0) {
  console.error(`✗ Design system audit found ${problems.length} problem(s):`);
  for (const { file, line, message } of problems) console.error(`  ${file}:${line}  ${message}`);
  process.exit(1);
}

console.log("✓ Design system audit passed.");
